213	    /**
214	     * Run the simulation from its current state for a single step.
215	     * Iterate over the whole field updating the state of each actor.
216	     */
217	    public void simulateOneStep()
218	    {
219	        step++;
220	        time.incrementTime(); 
221	        weatherCond = weatherCond.nextCondition();
222	        // Provide space for newborn actors.
223	
224	        List<Actor> newActors = new ArrayList<>();        
225	        // Let all actors act.
226	        for(Iterator<Actor> it = actors.iterator(); it.hasNext(); ) {
227	            Actor actor = it.next();
228	            actor.act(newActors, weatherCond);
229	            if(! actor.isAlive()) {
230	                it.remove();
231	            }
232	        }
233	
234	        // Add the newly born actors to the main lists.
235	        actors.addAll(newActors);
236	
237	        view.showStatus(step, field, weatherCond, diseases);
238	        field.setWeatherField(weatherCond);
239	    }
